import { SITE } from "@/config/site";
import Layout from "@/layouts/Layout.astro";
import { formatDate } from "@/utils/date";

interface Slide {
	url: string;
	date: string;
	title: string;
	description?: string;
}

interface SlidesResponse {
	slides?: Slide[];
}

function isSlide(value: unknown): value is Slide {
	if (typeof value !== "object" || value === null) return false;
	const slide = value as Record<string, unknown>;
	return (
		typeof slide.url === "string" &&
		typeof slide.date === "string" &&
		typeof slide.title === "string" &&
		(slide.description === undefined || typeof slide.description === "string")
	);
}

function parseSlidesResponse(value: unknown): Slide[] {
	if (typeof value !== "object" || value === null) return [];
	const slides = (value as SlidesResponse).slides;
	if (!Array.isArray(slides)) return [];
	return slides.filter(isSlide);
}

let slides: Slide[] = [];
let error: string | null = null;

try {
	const res = await fetch(`${SITE.slidesUrl}/slides.json`, {
		signal: AbortSignal.timeout(10000),
	});
	if (res.ok) {
		slides = parseSlidesResponse(await res.json());
	} else {
		error = "スライドを取得できませんでした";
	}
} catch {
	error = "スライドを取得できませんでした";
}
