---
import Button from "@/components/ui/Button.astro";
import { FEATURED_WORKS, HOME_CTAS, SITE } from "@/config/site";

const isExternalHref = (href: string) =>
	href.startsWith("https://") || href.startsWith("http://");
---

<section id="hero" class="hero" aria-labelledby="hero-name">
	<div class="hero-atmosphere" aria-hidden="true">
		<canvas class="hero-canvas" data-hero-canvas></canvas>
		<div class="hero-fallback">
			<div class="hero-wash hero-wash--a"></div>
			<div class="hero-wash hero-wash--b"></div>
		</div>
		<div class="hero-grain"></div>
	</div>

	<div class="hero-content">
		<div class="hero-copy">
			<p class="hero-handle">{SITE.handle}</p>
			<h1 id="hero-name" class="hero-name font-display">{SITE.name}</h1>
			<p class="hero-tagline">{SITE.tagline}</p>

			{
				FEATURED_WORKS.length > 0 && (
					<section
						class="hero-featured"
						aria-labelledby="hero-featured-heading"
					>
						<h2 id="hero-featured-heading" class="hero-featured-heading">
							代表作
						</h2>
						<ul class="hero-featured-list">
							{FEATURED_WORKS.map((work) => {
								const external = isExternalHref(work.href);
								return (
									<li>
										<a
											href={work.href}
											class="hero-featured-link"
											data-featured-work
											target={external ? "_blank" : undefined}
											rel={
												external
													? "noopener noreferrer"
													: undefined
											}
										>
											<span class="hero-featured-title">
												{work.title}
											</span>
											<span class="hero-featured-excerpt">
												{work.excerpt}
											</span>
										</a>
									</li>
								);
							})}
						</ul>
					</section>
				)
			}

			<nav class="hero-cta" aria-label="主なページ">
				{
					HOME_CTAS.map((cta) => (
						<Button href={cta.href} variant={cta.variant} size="md">
							{cta.label}
						</Button>
					))
				}
			</nav>
		</div>
	</div>
</section>

<style>
	.hero {
		position: relative;
		isolation: isolate;
		min-height: 100%;
		overflow: hidden;
		background: #faf9f6;
	}

	.hero-atmosphere {
		position: absolute;
		inset: 0;
		z-index: 0;
	}

	.hero-canvas {
		position: absolute;
		inset: 0;
		width: 100%;
		height: 100%;
		display: block;
		opacity: 0;
		transition: opacity 0.8s ease;
	}

	.hero.is-webgl .hero-canvas {
		opacity: 1;
	}

	.hero.is-webgl .hero-fallback {
		opacity: 0;
	}

	.hero-fallback {
		position: absolute;
		inset: 0;
		transition: opacity 0.5s ease;
	}

	.hero-wash {
		position: absolute;
		border-radius: 50%;
		filter: blur(80px);
